INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('b5d2b2bc-a53f-404c-874f-2bad25f06888', '251bc664-bb50-4543-b893-c9a28a926bca', 'en', 'Polish producer of premium modular architecture (COCOMODULE brand, Coco Design Sp. z o.o.), designing and building since 2017. The range covers COCOHOUSE year-round modular homes (COCO, LOFT and CUBE lines), hotel modules, COCOSPA garden saunas, COCOCAFE modular cafés and restaurants, and POP-UP pavilions. Structures are built in CLT (cross-laminated timber) or CWP (laminate and XPS) technology, with a distinctive rounded shape and large glazing. An in-house design office also prepares custom projects.', NULL, NULL, '2026-11-16T22:22:25.047Z'::timestamptz, '2026-11-16T22:22:25.047Z'::timestamptz) ON CONFLICT ("producer_id", "locale") DO UPDATE SET "description" = EXCLUDED."description", "showroom_visit_note" = EXCLUDED."showroom_visit_note", "inquiry_response_time_label" = EXCLUDED."inquiry_response_time_label", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('ab6d7177-e6f2-4461-9a68-764115fc9fc9', '251bc664-bb50-4543-b893-c9a28a926bca', 'de', 'Polnischer Hersteller von Premium-Modularchitektur (Marke COCOMODULE, Coco Design Sp. z o.o.), der seit 2017 plant und baut. Das Angebot umfasst ganzjährig bewohnbare Modulhäuser COCOHOUSE (Linien COCO, LOFT und CUBE), Hotelmodule, Gartensaunen COCOSPA, modulare Cafés und Restaurants COCOCAFE sowie POP-UP-Pavillons. Die Konstruktionen entstehen in CLT-Technologie (Brettsperrholz) oder CWP (Laminat und XPS), mit charakteristisch abgerundetem Baukörper und großen Verglasungen. Ein eigenes Planungsbüro erstellt auch Projekte nach Maß.', NULL, NULL, '2026-11-16T22:22:25.047Z'::timestamptz, '2026-11-16T22:22:25.047Z'::timestamptz) ON CONFLICT ("producer_id", "locale") DO UPDATE SET "description" = EXCLUDED."description", "showroom_visit_note" = EXCLUDED."showroom_visit_note", "inquiry_response_time_label" = EXCLUDED."inquiry_response_time_label", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('41c6b0f4-dc75-4099-8453-2a0ed935ca2c', '251bc664-bb50-4543-b893-c9a28a926bca', 'nl', 'Poolse producent van premium modulaire architectuur (merk COCOMODULE, Coco Design Sp. z o.o.), die sinds 2017 ontwerpt en bouwt. Het aanbod omvat jaarrond bewoonbare modulaire woningen COCOHOUSE (lijnen COCO, LOFT en CUBE), hotelmodules, tuinsauna''s COCOSPA, modulaire cafés en restaurants COCOCAFE en POP-UP-paviljoens. De constructies worden gebouwd in CLT (kruislaaghout) of CWP (laminaat en XPS), met een kenmerkende afgeronde vorm en grote beglazing. Een eigen ontwerpbureau maakt ook projecten op maat.', NULL, NULL, '2026-11-16T22:22:25.047Z'::timestamptz, '2026-11-16T22:22:25.047Z'::timestamptz) ON CONFLICT ("producer_id", "locale") DO UPDATE SET "description" = EXCLUDED."description", "showroom_visit_note" = EXCLUDED."showroom_visit_note", "inquiry_response_time_label" = EXCLUDED."inquiry_response_time_label", "updated_at" = EXCLUDED."updated_at";
