-- Cocomodule: opis producenta (kraj PL), tłumaczenia, konfigurator saun COCO (9 grup opcji).
UPDATE producer SET country_code = 'PL', description = 'Polski producent architektury modułowej premium (marka COCOMODULE, Coco Design Sp. z o.o.), projektujący i budujący od 2017 roku. W ofercie są całoroczne domy modułowe COCOHOUSE (linie COCO, LOFT i CUBE), moduły hotelowe, sauny ogrodowe COCOSPA, modułowe kawiarnie i restauracje COCOCAFE oraz pawilony POP-UP. Konstrukcje powstają w technologii CLT (drewno klejone krzyżowo) lub CWP (laminat i XPS), z charakterystyczną zaokrągloną bryłą i dużymi przeszkleniami. Własne biuro projektowe przygotowuje też projekty na zamówienie.', updated_at = now() WHERE id = '251bc664-bb50-4543-b893-c9a28a926bca';
UPDATE product_option SET is_default = false WHERE group_id IN (select id from product_option_group where producer_id = '251bc664-bb50-4543-b893-c9a28a926bca');
